INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der Chipsatz immer direkt auf der CPU integriert?', 2, '[{"text": "Nein", "correct": true, "because": "Oft auf dem Mainboard separat"}, {"text": "Ja", "correct": false, "because": "Nicht bei allen Architekturen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe übernimmt der Chipsatz auf einem Mainboard?', 3, '[{"text": "Verbindung von CPU und Peripherie", "correct": true, "because": "Koordiniert Datenfluss"}, {"text": "Stromversorgung regeln", "correct": false, "because": "Aufgabe des Netzteils"}, {"text": "Grafik rendern", "correct": false, "because": "GPU-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten steuert ein Chipsatz?', 5, '[{"text": "RAM", "correct": true, "because": "Speicherzugriff koordiniert"}, {"text": "PCIe-Lanes", "correct": true, "because": "Erweiterungsschnittstellen"}, {"text": "Taktfrequenz", "correct": false, "because": "CPU-intern"}, {"text": "Festplatte", "correct": false, "because": "Nur indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Chipsatz enthält Northbridge und Southbridge. b) Er ist bei modernen CPUs überflüssig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Moderne CPUs integrieren Teile, aber nicht alles"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Chipsatzes?', 4, '[{"text": "Kompatibilität zur CPU", "correct": false, "because": "Muss passen"}, {"text": "Anzahl der USB-Ports", "correct": false, "because": "Wichtig für Peripherie"}, {"text": "Farbe des Mainboards", "correct": true, "because": "Rein ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Chipsatz die GPU ersetzt?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Schnittstelle, keine Grafik"}, {"text": "Ja", "correct": false, "because": "Verwechselbar bei integrierter Grafik"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der Chipsatz bei der Datenübertragung?', 3, '[{"text": "Verbindet Komponenten", "correct": true, "because": "Bus-Systeme steuern"}, {"text": "Verschlüsselt Daten", "correct": false, "because": "Softwareaufgabe"}, {"text": "Erhöht Bandbreite", "correct": false, "because": "Hardware-abhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen übernimmt ein Chipsatz?', 5, '[{"text": "SATA-Steuerung", "correct": true, "because": "Festplattenanschluss"}, {"text": "USB-Management", "correct": true, "because": "Peripheriegeräte"}, {"text": "CPU-Kühlung", "correct": false, "because": "Physische Aufgabe"}, {"text": "Betriebssystemstart", "correct": false, "because": "BIOS/UEFI"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Der Chipsatz steuert den Speicherzugriff. b) Er ist nur für alte Systeme relevant. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch in modernen Systemen wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Chipsatz unwichtig?', 4, '[{"text": "PCIe-Unterstützung", "correct": false, "because": "Wichtig für Erweiterungen"}, {"text": "Southbridge-Funktion", "correct": false, "because": "Peripheriesteuerung"}, {"text": "Monitorauflösung", "correct": true, "because": "GPU-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Chipsatz für die Taktfrequenz verantwortlich?', 2, '[{"text": "Nein", "correct": true, "because": "CPU-intern geregelt"}, {"text": "Ja", "correct": false, "because": "Verwechselbar mit Bus-Takt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstellen hängen vom Chipsatz ab?', 4, '[{"text": "USB", "correct": true, "because": "Peripherieanschluss"}, {"text": "SATA", "correct": true, "because": "Speichermedien"}, {"text": "HDMI", "correct": false, "because": "GPU-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Chipsatz die Leistung der CPU bestimmt. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Nur unterstützend, nicht bestimmend"}, {"text": "Ja", "correct": false, "because": "CPU-leistungsabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Chipsatz?', 3, '[{"text": "Kompatibilität", "correct": true, "because": "Muss zur CPU passen"}, {"text": "Design", "correct": false, "because": "Ästhetisch, nicht funktional"}, {"text": "Preis allein", "correct": false, "because": "Funktion wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Chipsatz steuert I/O. b) Er ersetzt die CPU.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "CPU bleibt zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein moderner Chipsatz?', 5, '[{"text": "Schnellere Peripherie", "correct": true, "because": "USB 3.0, PCIe 4.0"}, {"text": "Mehr Anschlüsse", "correct": true, "because": "Erweitert Konnektivität"}, {"text": "Höhere Taktfrequenz", "correct": false, "because": "CPU-spezifisch"}, {"text": "Bessere Grafik", "correct": false, "because": "GPU-aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Chipsatz irrelevant?', 3, '[{"text": "RAM-Steuerung", "correct": false, "because": "Kernaufgabe"}, {"text": "SATA-Ports", "correct": false, "because": "Speicherverbindung"}, {"text": "Betriebssystem", "correct": true, "because": "Software-ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt der Chipsatz auch Netzwerkfunktionen?', 3, '[{"text": "Ja", "correct": true, "because": "LAN-Controller oft integriert"}, {"text": "Nein", "correct": false, "because": "Nicht immer extern"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Chipsatz bei Laptops anders ist?', 2, '[{"text": "Ja", "correct": true, "because": "Optimiert für Mobilität"}, {"text": "Nein", "correct": false, "because": "Grundfunktion gleich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponente wähle ich, wenn der Chipsatz fehlt?', 4, '[{"text": "Kein Ersatz möglich", "correct": true, "because": "Essenziell für Mainboard"}, {"text": "Zweite CPU", "correct": false, "because": "Keine Alternative"}, {"text": "Externer Controller", "correct": false, "because": "Unpraktisch"}]');
